const state={visibleCount:24,recipes:[],prices:{},ratings:{},user:null,csrf:'',favorites:new Set(),completed:new Set(),plan:null,cat:'todos',sort:'price',search:'',onlyFav:false,active:null,servings:2,step:0,authMode:'login',registrationOpen:false,selectedStore:'consum',timer:null,remaining:0,timerEnd:0,checked:new Set(),customs:{},pantry:{},shoppingStore:'consum',buyIndex:-1,plateIngredients:new Set(),plateType:'todos',plateStrict:false,fridge:{}};
